INSERT INTO products (id, public_id, seller_id, title, subtitle, category, icon, description, price, old_price, currency, stock, specs, rating_breakdown, badge, status, rejection_reason, reviewed_at, reviewed_by, rating, review_count, created_at) VALUES
(1, 'p1', 2, 'Lenovo ThinkPad E14 Gen 5', 'Ryzen 7 7730U · 16GB · 512GB', 'laptop', 'laptop', '16GB of RAM comfortably runs an IDE alongside Docker containers, and the 3-year local warranty matters more than raw benchmarks when you need this to survive four years of daily use.', 172500, 189000, 'LKR', 7, '{"RAM":"16GB DDR4","Storage":"512GB NVMe SSD","Battery":"10 hrs","Weight":"1.49 kg","Warranty":"3 years local"}', '{"5":74,"4":18,"3":5,"2":2,"1":1}', 'best match', 'active', NULL, NOW() - INTERVAL 86400 MINUTE, 1, 4.7, 128, NOW() - INTERVAL 89280 MINUTE),
(2, 'p2', 3, 'ASUS Vivobook 15 OLED', 'Core i5-1335U · 16GB · 512GB', 'laptop', 'laptop', 'Cheaper with a noticeably better OLED screen, but a shorter battery life and a one-year warranty make it the value pick rather than the long-haul pick.', 164900, NULL, 'LKR', 4, '{"RAM":"16GB DDR4","Storage":"512GB SSD","Battery":"7 hrs","Weight":"1.7 kg","Warranty":"1 year"}', '{"5":58,"4":26,"3":10,"2":4,"1":2}', NULL, 'active', NULL, NOW() - INTERVAL 84960 MINUTE, 1, 4.4, 86, NOW() - INTERVAL 87840 MINUTE),
(3, 'p3', 3, 'ASUS TUF Gaming F15', 'Core i7 · RTX 3050 · 16GB', 'laptop', 'laptop', 'The RTX 3050 handles most current titles at 1080p high settings, and the TUF chassis is built for heat — the trade-off is weight and a battery that won''t last a lecture day.', 245000, NULL, 'LKR', 3, '{"RAM":"16GB DDR5","Storage":"512GB SSD","GPU":"RTX 3050 6GB","Battery":"5 hrs","Warranty":"2 years"}', NULL, 'new', 'active', NULL, NOW() - INTERVAL 83520 MINUTE, 1, 4.6, 54, NOW() - INTERVAL 86400 MINUTE),
(4, 'p4', 4, 'Samsung Galaxy A55 5G', '128GB · 8GB RAM', 'phone', 'phone', 'Optical image stabilisation is the reason low-light shots come out sharp here, and five years of software updates means it stays secure long after cheaper rivals stop receiving patches.', 139000, 149000, 'LKR', 12, '{"Battery":"5000 mAh","Camera":"50MP OIS","Display":"6.6\\" AMOLED 120Hz","Updates":"5 years","Warranty":"1 year"}', '{"5":68,"4":22,"3":6,"2":3,"1":1}', 'trending', 'active', NULL, NOW() - INTERVAL 82080 MINUTE, 1, 4.6, 210, NOW() - INTERVAL 84960 MINUTE),
(5, 'p5', 4, 'Xiaomi Redmi Note 13 ', '256GB · 8GB RAM', 'phone', 'phone', 'More storage and a bigger battery for twenty thousand less — the catch is a shorter update window, so it ages faster in software terms even if the hardware holds up.', 118000, NULL, 'LKR', 9, '{"Battery":"5100 mAh","Camera":"200MP","Display":"6.67\\" AMOLED 120Hz","Updates":"2 years","Warranty":"1 year"}', NULL, 'deal', 'active', NULL, NOW() - INTERVAL 80640 MINUTE, 1, 4.3, 176, NOW() - INTERVAL 83520 MINUTE),
(6, 'p6', 2, 'Sony WH-CH520', 'Wireless over-ear', 'audio', 'headphones', 'Fifty hours of playback means charging roughly once a fortnight, which is the single feature people actually notice day to day at this price.', 12900, 15500, 'LKR', 25, '{"Battery":"50 hrs","Type":"Over-ear wireless","Codec":"SBC \\/ AAC","Warranty":"1 year"}', '{"5":62,"4":25,"3":8,"2":3,"1":2}', NULL, 'active', NULL, NOW() - INTERVAL 79200 MINUTE, 1, 4.5, 340, NOW() - INTERVAL 82080 MINUTE),
(7, 'p7', 5, 'LG 190L Inverter Refrigerator', 'Single door · Smart inverter', 'appliance', 'fridge', '190 litres is comfortable for a family of four to five, and the inverter compressor is the part that keeps the monthly electricity bill down over years of running.', 118000, 135000, 'LKR', 5, '{"Capacity":"190 L","Type":"Single door","Compressor":"Smart inverter","Warranty":"10 yr compressor"}', NULL, 'deal', 'active', NULL, NOW() - INTERVAL 77760 MINUTE, 1, 4.7, 62, NOW() - INTERVAL 80640 MINUTE),
(8, 'p8', 2, 'Canon EOS M50 Mark II', 'Mirrorless · 15-45mm kit', 'camera', 'camera', 'The vari-angle screen and clean autofocus make this the practical choice for filming yourself, which is what most buyers at this price are actually doing.', 189500, NULL, 'LKR', 2, '{"Sensor":"24.1MP APS-C","Video":"4K \\/ 1080p60","Screen":"Vari-angle touch","Warranty":"1 year"}', NULL, NULL, 'active', NULL, NOW() - INTERVAL 76320 MINUTE, 1, 4.5, 41, NOW() - INTERVAL 79200 MINUTE),
(9, 'p9', 2, 'HP Pavilion 15 (Ryzen 5 7530U)', 'Ryzen 5 · 16GB · 512GB · 15.6" FHD', 'laptop', 'laptop', 'A sensible mid-range laptop for students and office work — the 16GB of RAM is the reason to pick it over the 8GB competition at this price.', 215000, NULL, 'LKR', 6, '{"RAM":"16GB DDR4","Storage":"512GB NVMe","Display":"15.6\\" FHD IPS","Warranty":"2 years"}', NULL, NULL, 'pending', NULL, NULL, NULL, 0.0, 0, NOW() - INTERVAL 1800 MINUTE),
(10, 'p10', 4, 'Samsung Galaxy Buds FE', 'ANC · 30h with case · IPX2', 'audio', 'headphones', 'Entry-level ANC earbuds that pair well with Galaxy phones. Not for audiophiles — for commuters.', 24500, 27900, 'LKR', 15, '{"ANC":"Yes","Battery":"6h + 24h case","Water":"IPX2"}', NULL, NULL, 'pending', NULL, NULL, NULL, 0.0, 0, NOW() - INTERVAL 480 MINUTE);
