INSERT INTO reviews (product_id, user_id, rating, review_text, is_verified_buyer, helpful_count, created_at) VALUES
(1, 11, 5, 'Been running Docker plus IntelliJ on this for three months without a stutter. The 16GB is doing the heavy lifting — I never think about RAM anymore. Build quality is proper ThinkPad.', 1, 24, '2026-06-18 12:00:00'),
(1, 12, 5, 'Bought it mainly for the 3-year local warranty and I''m glad I did — had a keyboard issue in month two, sorted in Colombo in four days, no shipping abroad.', 1, 16, '2026-05-02 12:00:00'),
(1, 13, 4, 'Battery genuinely lasts a full lecture day. Only gripe is the screen — it''s fine, but after seeing an OLED I can tell the difference. Everything else is excellent.', 1, 9, '2026-04-21 12:00:00'),
(1, 14, 5, 'Keyboard is the best I''ve typed on in this price range. Runs cool even with a dozen tabs and a compile going.', 0, 5, '2026-03-09 12:00:00'),
(1, 15, 4, 'Solid workhorse. A bit plain looking if you care about that, but it does exactly what it says.', 1, 3, '2026-02-14 12:00:00'),
(2, 16, 5, 'The OLED screen is the whole reason to buy this. Colours are gorgeous and text is razor sharp — I stare at it eight hours a day and my eyes are happier.', 1, 19, '2026-06-30 12:00:00'),
(2, 17, 4, 'Great value for the money. Battery is the weak point exactly as described — I get about 6-7 hours, so I carry the charger. Worth it for the display.', 1, 12, '2026-05-19 12:00:00'),
(2, 18, 4, 'Light enough to carry all day and handles my coursework fine. One year warranty is short, that''s my only real complaint.', 1, 6, '2026-04-03 12:00:00'),
(2, 19, 5, 'Cheaper than the ThinkPad and the screen is better. For my use — writing and browsing — it was the obvious pick.', 0, 2, '2026-02-27 12:00:00'),
(4, 20, 5, 'The stabilisation is real — night shots at a wedding came out sharp where my old phone would have smeared everything. Camera alone justifies the price.', 1, 31, '2026-07-05 12:00:00'),
(4, 21, 5, 'Five years of updates is why I chose this over the cheaper options. I keep phones for four years, so that maths matters more than a spec sheet.', 1, 18, '2026-06-11 12:00:00'),
(4, 22, 4, 'Battery comfortably does a day and a half. Charging is not the fastest, but I charge overnight anyway so it has never bothered me.', 1, 11, '2026-05-08 12:00:00'),
(4, 23, 5, 'Screen is bright enough to read in direct sun in Colombo, which was my main worry. Very happy.', 1, 7, '2026-03-22 12:00:00'),
(4, 24, 4, 'Good all-rounder. Slightly heavier than I expected but the camera makes up for it.', 0, 4, '2026-02-02 12:00:00'),
(6, 25, 5, 'Fifty hours is not marketing — I charge these roughly once a fortnight. For the price there is genuinely nothing close.', 1, 27, '2026-07-12 12:00:00'),
(6, 26, 4, 'Comfortable for long flights and they fold flat into a bag. No active noise cancelling at this price, which is fair — just don''t expect it.', 1, 14, '2026-06-04 12:00:00'),
(6, 27, 5, 'Bought as a gift and ended up buying a second pair for myself. Light, simple, the battery is the killer feature.', 1, 8, '2026-04-17 12:00:00'),
(6, 28, 4, 'Sound is clean if unexciting. Perfect for podcasts and calls, which is what I wanted.', 0, 3, '2026-03-01 12:00:00');
