INSERT INTO faqs (category, sort_order, question, answer) VALUES
('ordering', 0, 'How does the AI consultant choose what to recommend?', 'It reads your budget and use-case from what you type, then matches against the live catalogue. If nothing fits, it says so rather than forcing a match.'),
('ordering', 1, 'Why was my order split into several shipments?', 'Each seller ships their own items. One checkout becomes one sub-order per seller, each with its own tracking and delivery.'),
('payments', 2, 'When is the seller paid?', 'Your payment is held in escrow and released to the seller only after you confirm delivery. If something goes wrong, the funds are still with us.'),
('payments', 3, 'Can I get a refund?', 'Yes — open a dispute from your order within 7 days of delivery. An admin reviews it and can refund the sub-order in full.'),
('sellers', 4, 'How long does seller verification take?', 'Usually 1–2 business days. We check your NIC and business registration before your storefront goes live.'),
('sellers', 5, 'What commission does Consult charge?', 'A flat platform rate (currently 8%) on each delivered sub-order, deducted before payout. Some sellers have a negotiated rate.');
